#include <bits/stdc++.h>
using namespace std;

constexpr int MOD = 1000000007;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, K;
    cin >> n >> K;

    if (K == 1) {
        cout << (n + 1LL) % MOD << '\n';
        return 0;
    }

    vector<int> dp(K, 0);
    long long total = 0;

    for (int i = 0; i < n; ++i) {
        int value = i;
        int u = 0;

        while (value) {
            u += value % K;
            value /= K;
        }
        u %= K;

        int next = (total + 1) % MOD;
        total = (total - dp[u] + next + MOD) % MOD;
        dp[u] = next;
    }

    cout << (total + 1) % MOD << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

constexpr int MOD = 1000000007;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    int K;
    cin >> n >> K;

    vector<int> dp(K, 0);
    int total = 0;
    int u = 0;

    for (long long i = 0; i < n; ++i) {
        int old = dp[u];
        dp[u] = (total + 1) % MOD;
        total = ((total - old + dp[u]) % MOD + MOD) % MOD;

        if (K > 1) {
            long long v = i;
            int carries = 0;
            while (v % K == K - 1) {
                ++carries;
                v /= K;
            }
            u = (u + 1 + carries) % K;
        }
    }

    cout << (total + 1) % MOD << '\n';
    return 0;
}

