using namespace std;

constexpr int MOD = 1000000007;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, K;
    cin >> n >> K;

    if (K == 1) {
        cout << (n + 1LL) % MOD << '\n';
        return 0;
    }

    vector<int> dp(K, 0);
    int total = 0;

    for (int i = 0; i < n; ++i) {
        int value = i;
        int u = 0;

        while (value) {
            u += value % K;
            value /= K;
        }
        u %= K;

        int old = dp[u];
        dp[u] = total + 1;
        if (dp[u] >= MOD) dp[u] -= MOD;

        total = (total - old + dp[u]) % MOD;
        if (total < 0) total += MOD;
    }

    cout << (total + 1LL) % MOD << '\n';
    return 0;
}

